// Course-owned tools. No mailbox credentials or automatic background mail access.
let learningPurpose='study',learningDraftScope='',workspaceCourse='',workspaceTab='notes',workspaceNotes=[],workspaceEvents=[],workspaceLinks=[],workspaceNote=null,workspaceSaveTimer=null,workspaceSaving=null,workspaceDirty=false,workspaceEpoch=0,mailCandidates=[],workspaceImportKind='mail',workspaceSourceEvidence='';
const purposeLabel=p=>({study:'学习',assignment:'作业辅导',exam:'考前复习',planning:'选课与学期规划'}[p]||'学习');
function draftKey(){return session?'courselex-draft:'+session.user.id+':'+assistantScope+':'+(learningThread?.id||'new'):''}
function saveLearningDraft(){try{const key=learningDraftScope||draftKey();if(key)sessionStorage.setItem(key,learningDraft)}catch{}}
function restoreLearningDraft(){const key=draftKey();if(key===learningDraftScope)return;learningDraftScope=key;try{learningDraft=sessionStorage.getItem(key)||''}catch{learningDraft=''}}
function courseDialog(title,body){const old=document.getElementById('courseDialog');if(old){if(workspaceDirty)return false;old.remove()}const dialog=document.createElement('dialog');dialog.id='courseDialog';dialog.className='courseDialog';dialog.innerHTML=`<header><h2>${esc(title)}</h2><button type="button" onclick="closeCourseDialog()" aria-label="关闭">✕</button></header><div id="courseDialogBody">${body}</div>`;document.body.append(dialog);dialog.addEventListener('cancel',e=>{if(workspaceDirty){e.preventDefault();saveWorkspaceNote().then(ok=>{if(ok)dialog.close()})}});dialog.addEventListener('close',()=>{if(document.getElementById('courseDialog')===dialog){workspaceEpoch++;clearTimeout(workspaceSaveTimer)}dialog.remove()});dialog.showModal();return true}
function courseOptions(selected){return courseRows.filter(c=>!c.archived&&!c.is_shared_template).map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.code&&c.code!==c.name?c.code+' · '+c.name:c.name)}</option>`).join('')}
function courseSelectControl(id,selected,callback=''){
 const rows=courseRows.filter(c=>!c.archived&&!c.is_shared_template),current=rows.find(c=>c.id===selected);
 return `<input type="hidden" id="${id}" value="${current?.id||''}"><details class="courseSwitcher workspacePicker" id="${id}Picker"><summary><span>${esc(current?.code||current?.name||'选择课程')}</span><span class="pickerChevron">⌄</span></summary><div class="courseMenu">${rows.map(c=>`<button type="button" onclick="pickCourseControl('${id}','${c.id}','${callback}')">${esc(c.code||c.name)}${c.name!==c.code?`<small>${esc(c.name)}</small>`:''}</button>`).join('')}</div></details>`;
}
function pickCourseControl(id,value,callback){const input=document.getElementById(id),picker=document.getElementById(id+'Picker'),course=courseRows.find(c=>c.id===value&&!c.archived);if(!input||!picker||!course)return;input.value=value;picker.querySelector('summary span').textContent=course.code||course.name;picker.open=false;if(callback==='workspace')switchWorkspaceCourse(value)}
function showNewLearningDialog(){if(assistantBusy)return;courseDialog('新对话',`<label for="newThreadCourse">保存到课程</label>${courseSelectControl('newThreadCourse',assistantScope)}<p id="newCourseNotice" role="status"></p><p class="workspaceHint">只使用这门课的资料，每次作业可以单独开一个话题。</p><div class="purposeChoices">${['study','assignment','exam'].map(p=>`<button class="secondary" onclick="beginPurposeThread('${p}')">${purposeLabel(p)}</button>`).join('')}</div><hr><button class="newChat" onclick="beginSemesterPlanning()">准备开学？先做选课与学期规划 ↗</button>`)}
function beginPurposeThread(purpose){const course=document.getElementById('newThreadCourse');if(!course.value){document.getElementById('newCourseNotice').textContent='请选择要保存学习记录的课程。';return}const value=course.value;closeCourseDialog();changeLearningScope(value);clearLearningConversation();learningPurpose=purpose;document.getElementById('materialPrompt')?.focus()}
async function showAllLearningThreads(){if(assistantBusy)return;try{const epoch=accountEpoch,result=await coursewareRequest({action:'learning_threads'});if(epoch!==accountEpoch)return;learningState.threads=result.threads;toggleLearningDrawer()}catch(e){alert('记录暂时无法加载：'+e.message)}}
function renameLearningThread(){if(!learningThread||assistantBusy)return;courseDialog('对话名称',`<form onsubmit="saveLearningThreadTitle(event)"><label for="threadTitle">名称</label><input id="threadTitle" maxlength="100" value="${esc(learningThread.title)}" required><button class="secondary">保存名称</button><p id="threadTitleError" role="alert"></p></form>`)}
async function saveLearningThreadTitle(event){event.preventDefault();const title=document.getElementById('threadTitle').value.trim();if(!title)return;try{await coursewareRequest({action:'learning_rename',thread:learningThread.id,title});learningThread.title=title;await closeCourseDialog();renderStudyAssistant()}catch(e){document.getElementById('threadTitleError').textContent=e.message}}
function workspaceScope(){const rows=courseRows.filter(c=>!c.archived&&!c.is_shared_template);return rows.some(c=>c.id===assistantScope)?assistantScope:rows.length===1?rows[0].id:''}
async function showCourseWorkspace(tab='notes',courseId){
 if((workspaceDirty||workspaceSaving)&&!await flushWorkspace())return;
 if(tab==='materials')return openCourseMaterials(courseId);
 if(!session)return;workspaceCourse=courseRows.some(c=>c.id===courseId&&!c.archived)?courseId:workspaceScope();if(!workspaceCourse){chooseToolCourse(tab);return}
 const heading={notes:'学习笔记',calendar:'学习安排',links:'学校链接'}[tab]||'学习笔记';
 if(!courseDialog(heading,`<div class="focusedToolScope">${courseSelectControl('workspaceCourse',workspaceCourse,'workspace')}</div><div id="workspaceContent" aria-live="polite">正在加载…</div>`))return;
 workspaceNote=null;workspaceTab=tab;await loadCourseWorkspace();
}
async function openWorkspaceMaterials(){if(!await flushWorkspace())return;closeCourseDialog();openCourseMaterials(workspaceCourse)}
async function switchWorkspaceCourse(course){if(!await flushWorkspace()){document.getElementById('workspaceCourse').value=workspaceCourse;return}workspaceCourse=course;workspaceNote=null;await loadCourseWorkspace()}
async function setWorkspaceTab(tab){if(!await flushWorkspace())return;workspaceNote=null;workspaceTab=tab;renderCourseWorkspace()}
async function loadCourseWorkspace(){const epoch=++workspaceEpoch,uid=session.user.id,course=workspaceCourse;try{const [notes,events,links]=await Promise.all([workspaceTab==='notes'?sb('user_course_notes?course_id=eq.'+course+'&order=updated_at.desc'):[],workspaceTab==='calendar'?sb('user_course_events?course_id=eq.'+course+'&order=starts_at.asc'):[],workspaceTab==='links'?sb('user_school_links?order=created_at.asc'):[]]);if(epoch!==workspaceEpoch||session?.user.id!==uid)return;workspaceNotes=notes;appendWorkspaceDrafts(uid,course);workspaceEvents=events;workspaceLinks=links;renderCourseWorkspace()}catch(e){if(epoch===workspaceEpoch)document.getElementById('workspaceContent').textContent='暂时无法加载：'+e.message}}
function calendarAiImportAvailable(){return window.SINQ_TRIAL_CAPABILITIES?.calendarAiImport!==false}
function renderCalendarImports(){if(!calendarAiImportAvailable())return '<div class="calendarTrialTools"><p class="workspaceHint">本轮试用暂未开放课程大纲和邮件的 AI 导入。请手动添加安排。</p><button class="newChat" onclick="exportWorkspaceCalendar()">导出日历文件</button></div>';return `<details class="workspaceAdvanced"><summary>导入与导出</summary><div>${calendarAiImportAvailable()?'<button class="newChat" onclick="showMailImport(\'syllabus\')">从课程大纲导入</button><button class="newChat" onclick="showMailImport()">从邮件整理</button>':'<p class="workspaceHint calendarTrialNotice">本轮试用暂未开放课程大纲和邮件的 AI 导入。请手动添加上课、作业、考试或复习安排。</p>'}<button class="newChat" onclick="exportWorkspaceCalendar()">导出日历文件</button></div></details>`}
function showCalendarImportLimit(){const area=document.getElementById('workspaceContent');if(!area)return;area.innerHTML='<section class="calendarImportLimit"><h3>本轮试用暂未开放 AI 导入</h3><p class="workspaceHint">课程大纲和邮件内容不会在这里提交给 AI。你仍然可以手动添加安排，并导出到自己的日历。</p><div class="workspaceRow"><button class="secondary" onclick="editWorkspaceEvent()">手动添加安排</button><button class="newChat" onclick="renderCourseWorkspace()">返回学习安排</button></div></section>'}
function renderCourseWorkspace(){const area=document.getElementById('workspaceContent');if(!area)return;document.querySelectorAll('.workspaceTabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===workspaceTab));
 if(workspaceTab==='notes')area.innerHTML=`<div class="workspaceRow"><p class="workspaceHint">按课程保存，自动同步到你的账号。</p><button class="secondary" onclick="openNotebookSplit()">课件分屏笔记</button><button class="newChat" onclick="editWorkspaceNote()">新建笔记</button><label class="newChat">导入笔记<input type="file" accept=".md,.txt,.docx,.pdf" hidden onchange="importWorkspaceNote(this.files[0])"></label></div>${workspaceNotes.length?workspaceNotes.map(n=>`<button class="noteItem" onclick="editWorkspaceNote('${n.id}')"><strong>${esc(n.title)}</strong><small>${new Date(n.updated_at).toLocaleString()}</small></button>`).join(''):'<p class="workspaceEmpty">讲解下方点“存为笔记”，也可以从空白开始写。</p>'}`;
 if(workspaceTab==='calendar')area.innerHTML=`<div class="workspaceRow"><button class="secondary" onclick="editWorkspaceEvent()">＋ 添加安排</button>${renderCalendarImports()}</div><p class="workspaceHint">${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)} · 截止时间按本机时区显示。导出后可加入手机、Google 或 Outlook 日历。</p>${workspaceEvents.length?workspaceEvents.map(e=>`<article class="calendarItem ${e.done?'isDone':''}"><label><input type="checkbox" ${e.done?'checked':''} onchange="completeWorkspaceEvent('${e.id}',this.checked)"><strong>${esc(e.title)}</strong></label><small>${esc({class:'上课',assignment:'作业截止',exam:'考试',review:'复习'}[e.kind])} · ${new Date(e.starts_at).toLocaleString('zh-CN',{year:'numeric',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}</small>${e.details?`<p>${esc(e.details)}</p>`:''}<button class="newChat" onclick="editWorkspaceEvent('${e.id}')">编辑</button><button class="newChat" onclick="deleteWorkspaceEvent('${e.id}')">删除</button></article>`).join(''):'<p class="workspaceEmpty">把上课、作业截止和考试放在这里。复习计划也能一键加入。</p>'}`;
 if(workspaceTab==='links'){const city=/city\s*(?:university|u)|城市大學|城市大学/i.test(userProfile?.school||'');const defaults=city?[{label:'学校官网',url:'https://www.cityu.edu.hk/'},{label:'Canvas',url:'https://canvas.cityu.edu.hk/'},{label:'学校图书馆',url:'https://www.cityu.edu.hk/lib/'}]:[];area.innerHTML=`<p class="workspaceHint">在新窗口打开学校服务，无需向莱克提供学校密码。</p>${defaults.concat(workspaceLinks).map(l=>`<div class="workspaceRow"><a class="schoolLink" href="${esc(safeSchoolURL(l.url)||'#')}" target="_blank" rel="noopener noreferrer">${esc(l.label)} ↗</a>${l.id?`<button class="newChat" onclick="deleteSchoolLink('${l.id}')">移除</button>`:''}</div>`).join('')}<form id="schoolLinkForm" onsubmit="addSchoolLink(event)"><label for="schoolLinkLabel">名称</label><input id="schoolLinkLabel" maxlength="60" required><label for="schoolLinkURL">网址</label><input type="url" id="schoolLinkURL" placeholder="https://" maxlength="2000" required><button class="secondary">添加链接</button></form>`}
}
async function flushWorkspace(){clearTimeout(workspaceSaveTimer);return workspaceDirty?await saveWorkspaceNote():workspaceSaving?await workspaceSaving:true}
async function closeCourseDialog(){if(!await flushWorkspace())return false;document.getElementById('courseDialog')?.close();return true}
function editWorkspaceNote(id){workspaceNote=id?{...workspaceNotes.find(n=>n.id===id)}:{id:crypto.randomUUID(),title:isNotebookSplit()&&readingPane.week?'Week '+readingPane.week+' · 学习笔记':'未命名笔记',body:'',paper_style:'blank',week:isNotebookSplit()?readingPane.week||null:null,version:0};workspaceDirty=false;try{const draft=readWorkspaceDraft(workspaceNote.id,workspaceCourse);if(draft){workspaceNote={...workspaceNote,title:draft.title,body:draft.body,paper_style:draft.paper_style||workspaceNote.paper_style||'blank',week:draft.week??workspaceNote.week??null,version:draft.version,_restoredDraft:true};workspaceDirty=true}}catch{}const n=workspaceNote,inline=isNotebookSplit();document.getElementById('workspaceContent').innerHTML=`<div class="workspaceRow">${inline?'':'<button class="newChat" onclick="backToWorkspaceNotes()">← 笔记</button>'}<span id="noteSaveStatus" role="status" aria-live="polite">${workspaceDirty?'已恢复本机未同步草稿':n.version?'本篇笔记已同步':'开始输入后自动保存'}</span></div><div id="noteConflict" role="alert" hidden></div><label class="srOnly" for="noteTitle">笔记标题</label><input id="noteTitle" value="${esc(n.title)}" maxlength="120" oninput="scheduleNoteSave()">${typeof noteEditorToolbar==='function'?noteEditorToolbar(n):''}<div id="noteSurface" class="noteSurface"><label class="srOnly" for="noteBody">笔记内容</label><textarea id="noteBody" class="noteEditor noteCanvas" maxlength="60000" placeholder="写下理解、问题或作业思路…支持 Markdown" oninput="scheduleNoteSave();updateNoteEditorState()">${esc(n.body)}</textarea><div id="noteReadView" class="noteReadView noteCanvas" hidden></div></div><div class="workspaceRow workspaceNoteActions"><button class="secondary" onclick="saveWorkspaceNote()">保存</button><button class="newChat" onclick="exportWorkspaceNote()" title="导出 Markdown 文字及图片引用，图片仍保存在笔记中">导出文字</button>${inline?'':'<button class="newChat" onclick="openNotebookSplit(workspaceNote.id)">课件分屏</button><button class="newChat" onclick="askAboutWorkspaceNote()">问莱克</button>'}<button class="newChat" onclick="copyConflictedNote()">另存一份</button>${inline?'':'<button class="newChat" onclick="deleteWorkspaceNote()">删除</button>'}</div>`;if(typeof initializeNoteEditor==='function')initializeNoteEditor(n);if(workspaceDirty){clearTimeout(workspaceSaveTimer);workspaceSaveTimer=setTimeout(saveWorkspaceNote,1000)}}
function scheduleNoteSave(){workspaceDirty=true;const label=document.getElementById('notebookPicker')?.querySelector?.('summary strong');if(label)label.textContent=document.getElementById('noteTitle')?.value.trim()||'未命名笔记';const durable=persistWorkspaceNoteDraft();document.getElementById('noteSaveStatus').textContent=durable?'已保存在本机，等待同步…':'本机持久保存不可用，正在尝试云端保存；请勿关闭页面';clearTimeout(workspaceSaveTimer);workspaceSaveTimer=setTimeout(saveWorkspaceNote,1000)}
async function saveWorkspaceNote(retry=0){if(workspaceSaving){await workspaceSaving;if(workspaceDirty)return saveWorkspaceNote();return true}if(!workspaceNote||!workspaceDirty)return true;const title=document.getElementById('noteTitle')?.value.trim()||'未命名笔记',body=document.getElementById('noteBody')?.value||'',paper_style=validNotePaper(document.getElementById('notePaperStyle')?.value||workspaceNote.paper_style),n={...workspaceNote},uid=session?.user.id,epoch=workspaceEpoch;workspaceDirty=false;const saveStatus=document.getElementById('noteSaveStatus');if(saveStatus)saveStatus.textContent='正在保存本篇笔记…';workspaceSaving=(async()=>{try{if(!n.version&&n._restoredDraft){const existing=await sb('user_course_notes?id=eq.'+n.id+'&course_id=eq.'+workspaceCourse);if(epoch!==workspaceEpoch||session?.user.id!==uid)return false;if(existing[0]){if(['title','body','paper_style'].some(k=>(existing[0][k]||'')!==({title,body,paper_style}[k]||''))){workspaceDirty=true;persistWorkspaceNoteDraft();showNoteConflict(existing[0]);return false}n.version=existing[0].version}}const rows=await sb('user_course_notes'+(n.version?'?id=eq.'+n.id+'&version=eq.'+n.version:''),{method:n.version?'PATCH':'POST',body:JSON.stringify(n.version?{title,body,paper_style}:{id:n.id,user_id:uid,course_id:workspaceCourse,title,body,paper_style,week:n.week||null})});if(epoch!==workspaceEpoch||session?.user.id!==uid)return false;if(!rows.length){
 const latest=await sb('user_course_notes?id=eq.'+n.id+'&course_id=eq.'+workspaceCourse);
 if(epoch!==workspaceEpoch||session?.user.id!==uid)return false;
 const remote=latest[0],local={title,body,paper_style},merged=remote&&!n._restoredDraft&&mergeNoteFields(n,local,remote);
 if(merged&&!workspaceDirty){workspaceNote=remote;document.getElementById('noteTitle').value=merged.title;document.getElementById('noteBody').value=merged.body;const paper=document.getElementById('notePaperStyle');if(paper)paper.value=merged.paper_style;workspaceDirty=true;persistWorkspaceNoteDraft();return true}
 workspaceDirty=true;persistWorkspaceNoteDraft();showNoteConflict(remote);return false}
 const conflict=document.getElementById('noteConflict');if(conflict)conflict.hidden=true;workspaceNote=rows[0];try{if(workspaceDirty)persistWorkspaceNoteDraft();else removeWorkspaceDraft(noteDraftKey(n.id),{title,body,paper_style})}catch{}workspaceNotes=[rows[0],...workspaceNotes.filter(x=>x.id!==n.id)];document.getElementById('noteSaveStatus').textContent=workspaceDirty?'还有新修改，正在保存…':'本篇笔记已同步';if(isNotebookSplit()){rememberNotebookNote(rows[0].id);renderNotebookControls()}return true}catch(e){if(epoch===workspaceEpoch){workspaceDirty=true;document.getElementById('noteSaveStatus').textContent=(persistWorkspaceNoteDraft()?'已保存在本机，尚未同步：':'未同步且本机持久保存失败，请保持页面打开并导出：')+e.message}return false}finally{workspaceSaving=null}})();const result=await workspaceSaving;if(result&&workspaceDirty){if(retry>=2){document.getElementById('noteSaveStatus').textContent='本篇笔记尚未同步：另一设备仍在编辑，文字已保留，请稍后再保存';return false}return saveWorkspaceNote(retry+1)}return result}
function mergeNoteFields(base,local,remote){
 const result={};for(const key of ['title','body','paper_style']){const b=base[key]||'',l=local[key]||'',r=remote[key]||'';if(l!==b&&r!==b&&l!==r)return null;result[key]=l===b?r:l}return result;
}
function showNoteConflict(remote){
 document.getElementById('noteSaveStatus').textContent='本篇笔记未同步：另一设备已更新，当前文字已保留在本机';
 const panel=document.getElementById('noteConflict');if(!panel)return;panel.hidden=false;
 panel.innerHTML='<p>两个设备修改了同一内容。为避免覆盖，请先保留当前版本。</p><button class="secondary" onclick="copyConflictedNote()">将当前文字另存为副本</button>'+(remote?'<button class="newChat" onclick="openLatestNoteSafely()">保留副本并打开云端原笔记</button>':'')+'<p>本篇笔记尚未保存到云端；解决冲突后再继续跨设备编辑。</p>';
}
async function copyConflictedNote(){
 clearTimeout(workspaceSaveTimer);if(workspaceSaving)await workspaceSaving;
 const original={...workspaceNote},oldKey=noteDraftKey(original.id);
 workspaceNote={...original,id:crypto.randomUUID(),title:(document.getElementById('noteTitle')?.value||original.title).slice(0,110)+' · 副本',version:0};
 document.getElementById('noteTitle').value=workspaceNote.title;workspaceDirty=true;persistWorkspaceNoteDraft();
 const ok=await saveWorkspaceNote();if(ok){try{removeWorkspaceDraft(oldKey)}catch{}}else{try{sessionStorage.setItem(oldKey,JSON.stringify({...original,course_id:workspaceCourse,body:document.getElementById('noteBody')?.value||''}))}catch{}}
 return ok;
}
async function openLatestNoteSafely(){
 const id=workspaceNote.id,course=workspaceCourse,uid=session?.user.id;
 if(!await copyConflictedNote())return;
 try{const rows=await sb('user_course_notes?id=eq.'+id+'&course_id=eq.'+course);if(session?.user.id!==uid||workspaceCourse!==course)return;if(!rows.length)throw Error('原笔记已不可用，当前副本已保存');workspaceNotes=[rows[0],...workspaceNotes.filter(n=>n.id!==id)];editWorkspaceNote(id);if(isNotebookSplit()){rememberNotebookNote(id);renderNotebookControls()}}catch(e){document.getElementById('noteSaveStatus').textContent=e.message}
}
async function backToWorkspaceNotes(){if(await flushWorkspace()){workspaceNote=null;renderCourseWorkspace()}}
function previewWorkspaceNote(){document.getElementById('notePreview').innerHTML=learningMarkdown(document.getElementById('noteBody').value)}
function downloadWorkspaceFile(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name.replace(/[\\/:*?"<>|]/g,'-');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportWorkspaceNote(){downloadWorkspaceFile((document.getElementById('noteTitle').value||'笔记')+'.md','# '+document.getElementById('noteTitle').value+'\n\n'+document.getElementById('noteBody').value)}
async function askAboutWorkspaceNote(){if(!await flushWorkspace())return;const course=workspaceCourse,body=document.getElementById('noteBody').value,title=document.getElementById('noteTitle').value;closeCourseDialog();changeLearningScope(course);clearLearningConversation();learningDraft='这是我的学习笔记（可能有错误，不是老师原文）：\n'+title+'\n'+(body.length>1500?'（以下为前 1500 字）\n':'')+body.slice(0,1500)+'\n请结合这门课的原文帮我检查理解。';saveLearningDraft();renderStudyAssistant()}
function messageNoteWeek(message,course){const weeks=[...new Set((message.citations||[]).map(c=>Number(c.week)).filter(w=>Number.isInteger(w)&&w>=1&&w<=52))];if(weeks.length===1)return weeks[0];if(weeks.length>1)return null;return isNotebookSplit()&&workspaceScope()===course?readingPane.week||null:null}
async function saveMessageNote(id){const m=learningThread?.messages.find(m=>m.id===id),course=learningThread?.course_id,uid=session?.user.id,title=(learningThread?.title||'莱克讲解').slice(0,120);if(!m||!course||!uid)return;const week=messageNoteWeek(m,course);try{const refs=(m.citations||[]).map(c=>`- ${c.filename} · Week ${c.week}：${c.quote}`).join('\n');if(!await flushWorkspace()||session?.user.id!==uid)return;const saved=await sb('user_course_notes',{method:'POST',body:JSON.stringify({user_id:uid,course_id:course,title,body:m.content+(refs?'\n\n## 课件依据\n'+refs:''),week})});if(session?.user.id!==uid)return;const note=saved[0];if(!note?.id)throw Error('未收到笔记保存结果');if(isNotebookSplit()){workspaceNotes=[note,...workspaceNotes.filter(n=>n.id!==note.id)];await openNotebookSplit(note.id,course)}else await showCourseWorkspace('notes',course)}catch(e){if(session?.user.id===uid)alert('笔记未保存：'+e.message)}}
function localDateValue(value){const d=new Date(value);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function editWorkspaceEvent(id,prefill={}){const e=workspaceEvents.find(e=>e.id===id)||prefill;workspaceSourceEvidence=!id&&e.evidence?e.evidence:'';document.getElementById('workspaceContent').innerHTML=`<form onsubmit="saveWorkspaceEvent(event,'${id||''}')"><label for="eventTitle">安排名称</label><input id="eventTitle" maxlength="160" value="${esc(e.title||'')}" required>${renderStudyPicker('eventKind','安排类型',e.kind||'assignment',[['class','上课'],['assignment','作业截止'],['exam','考试'],['review','复习']].map(([value,label])=>({value,label})),()=>{})}<label for="eventStart">时间 · ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}</label><input type="datetime-local" id="eventStart" value="${e.starts_at?localDateValue(e.starts_at):''}" required><label for="eventMinutes">时长（分钟）</label><input type="number" id="eventMinutes" min="1" max="1440" value="${e.ends_at?Math.max(1,Math.round((Date.parse(e.ends_at)-Date.parse(e.starts_at))/60000)):30}" required>${id?'':'<label for="eventRepeat">每周重复次数（包括本次）</label><input type="number" id="eventRepeat" min="1" max="30" value="1">'}<label for="eventDetails">备注</label><textarea id="eventDetails" maxlength="4000">${esc(e.details||'')}</textarea><div class="workspaceRow"><button class="secondary">保存安排</button><button type="button" class="newChat" onclick="renderCourseWorkspace()">取消</button></div><p id="eventError" role="alert"></p></form>`}
async function saveWorkspaceEvent(event,id){event.preventDefault();const form=event.target,button=form.querySelector('button');button.disabled=true;try{const d=new Date(document.getElementById('eventStart').value),minutes=Number(document.getElementById('eventMinutes').value),count=id?1:Number(document.getElementById('eventRepeat').value);if(!Number.isFinite(+d)||minutes<1||minutes>1440||count<1||count>30)throw Error('请检查时间、时长和重复次数。');const fields={title:document.getElementById('eventTitle').value.trim(),kind:document.getElementById('eventKind').value,details:document.getElementById('eventDetails').value,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone};const rows=Array.from({length:count},(_,i)=>{const at=new Date(d);at.setDate(at.getDate()+i*7);return {...fields,starts_at:at.toISOString(),ends_at:new Date(+at+minutes*60000).toISOString(),...(!id?{user_id:session.user.id,course_id:workspaceCourse}:{})}});if(!id&&workspaceSourceEvidence)for(const row of rows){const raw=JSON.stringify([workspaceCourse,row.kind,row.starts_at,workspaceSourceEvidence]);row.source_key='import:'+Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(raw)))).map(b=>b.toString(16).padStart(2,'0')).join('')}await sb('user_course_events'+(id?'?id=eq.'+id:workspaceSourceEvidence?'?on_conflict=user_id,source_key':''),{method:id?'PATCH':'POST',headers:!id&&workspaceSourceEvidence?{Prefer:'resolution=ignore-duplicates,return=representation'}:{},body:JSON.stringify(id?rows[0]:rows)});await loadCourseWorkspace()}catch(e){document.getElementById('eventError').textContent=e.message;button.disabled=false}}
async function completeWorkspaceEvent(id,done){try{const event=workspaceEvents.find(e=>e.id===id);if(event?.thread_id){const result=await coursewareRequest({action:'learning_calendar_task',event:id,done});if(learningThread?.id===result.thread?.id){learningThread=result.thread;renderLearningConversation()}}else await sb('user_course_events?id=eq.'+id,{method:'PATCH',body:JSON.stringify({done})});await loadCourseWorkspace()}catch(e){alert(e.message);await loadCourseWorkspace()}}
async function deleteWorkspaceEvent(id){if(!confirm('移除这条日历安排？'))return;try{await sb('user_course_events?id=eq.'+id,{method:'DELETE'});await loadCourseWorkspace()}catch(e){alert(e.message)}}
function calendarEscape(value){return String(value||'').replace(/\\/g,'\\\\').replace(/\r\n|\r|\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,')}
function calendarStamp(value){return new Date(value).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}
function calendarFold(line){let result='',part='',size=0;for(const ch of line){const n=new TextEncoder().encode(ch).length;if(size+n>73){result+=part+'\r\n ';part='';size=1}part+=ch;size+=n}return result+part}
function makeWorkspaceCalendar(events){return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//SINQ//Course Workspace//EN','CALSCALE:GREGORIAN',...events.filter(e=>!e.done).flatMap(e=>['BEGIN:VEVENT','UID:'+e.id+'@courselexai.com','DTSTAMP:'+calendarStamp(Date.now()),'DTSTART:'+calendarStamp(e.starts_at),'DTEND:'+calendarStamp(e.ends_at),'SUMMARY:'+calendarEscape(e.title),'DESCRIPTION:'+calendarEscape(e.details),'END:VEVENT']),'END:VCALENDAR'].map(calendarFold).join('\r\n')+'\r\n'}
function exportWorkspaceCalendar(){if(!workspaceEvents.some(e=>!e.done))return alert('还没有未完成的日历安排。');downloadWorkspaceFile((courseRows.find(c=>c.id===workspaceCourse)?.code||'SINQ')+'.ics',makeWorkspaceCalendar(workspaceEvents),'text/calendar;charset=utf-8')}
async function addPlanToCalendar(planId){const plan=learningThread?.messages.map(m=>m.plan).find(p=>p?.id===planId);if(!plan||!learningThread.course_id)return;if(!confirm('将这个复习计划加入本课程日历？时间按计划日期保留，可在课程空间调整。'))return;try{const rows=plan.tasks.map(t=>({user_id:session.user.id,course_id:learningThread.course_id,title:t.title,kind:'review',starts_at:t.due_at,ends_at:new Date(Date.parse(t.due_at)+t.minutes*60000).toISOString(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,details:t.prompt,done:t.done,thread_id:learningThread.id,task_id:t.id,source_key:'plan:'+t.id}));await sb('user_course_events?on_conflict=user_id,source_key',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates,return=representation'},body:JSON.stringify(rows)});await showCourseWorkspace('calendar')}catch(e){alert(e.message)}}
function safeSchoolURL(value){try{const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password||!u.hostname.includes('.'))return '';return u.href}catch{return ''}}
async function addSchoolLink(event){event.preventDefault();const url=safeSchoolURL(document.getElementById('schoolLinkURL').value);if(!url)return alert('请填写完整的 https 学校网址，不要包含账号或密码。');try{await sb('user_school_links',{method:'POST',body:JSON.stringify({user_id:session.user.id,label:document.getElementById('schoolLinkLabel').value.trim(),url})});await loadCourseWorkspace()}catch(e){alert(e.message)}}
async function deleteSchoolLink(id){try{await sb('user_school_links?id=eq.'+id,{method:'DELETE'});await loadCourseWorkspace()}catch(e){alert(e.message)}}
function showMailImport(kind='mail'){if(!calendarAiImportAvailable())return showCalendarImportLimit();workspaceImportKind=kind;mailCandidates=[];document.getElementById('workspaceContent').innerHTML=`<h3>${kind==='syllabus'?'从 syllabus 整理学期安排':'从邮件整理安排'}</h3><p class="workspaceHint">${kind==='syllabus'?'选择 PDF、Word 或 TXT syllabus，或粘贴课程大纲。莱克会提取上课、考试和作业日期，周期性上课可在确认时设置每周重复。':'支持 Gmail、Outlook 和学校邮件：复制你选择的邮件正文。'} 内容交给DeepSeek AI，逐条核对后才加入日历；原文不另存。</p><form onsubmit="extractWorkspaceMail(event)">${kind==='syllabus'?'<label class="fileDropControl"><span class="fileControlIcon">＋</span><span><strong>添加课程大纲</strong><small id="syllabusFilename">PDF、Word 或 TXT · 也可以粘贴下方</small></span><input class="srOnly" type="file" accept=".pdf,.docx,.txt" onchange="document.getElementById(&quot;syllabusFilename&quot;).textContent=this.files[0]?.name||&quot;PDF、Word 或 TXT&quot;;readSyllabusForCalendar(this.files[0])"></label>':''}<label for="mailText">${kind==='syllabus'?'课程大纲内容':'邮件正文'}</label><textarea id="mailText" rows="8" maxlength="24000" required></textarea><label for="mailConsent" class="workspaceConsent"><input id="mailConsent" type="checkbox" required>允许分析所选内容并提取学习安排</label><button class="secondary">提取并预览</button><button type="button" class="newChat" onclick="renderCourseWorkspace()">取消</button><p id="mailStatus" role="status"></p></form><div id="mailPreview"></div>`}
async function extractWorkspaceMail(event){event.preventDefault();if(!calendarAiImportAvailable())return showCalendarImportLimit();const button=event.target.querySelector('button');button.disabled=true;document.getElementById('mailStatus').textContent='正在整理，尚未写入日历…';const epoch=workspaceEpoch,course=workspaceCourse;try{const result=await coursewareRequest({action:'workspace_mail',course,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,kind:workspaceImportKind,text:document.getElementById('mailText').value,consent:true});if(epoch!==workspaceEpoch||course!==workspaceCourse)return;mailCandidates=result.events;document.getElementById('mailStatus').textContent=result.events.length?'请逐条核对日期、时区和课程；不确定的日期需要补齐。':'没有找到可确认的学习安排，可手动添加。';document.getElementById('mailPreview').innerHTML=mailCandidates.map((e,i)=>`<article class="calendarItem"><h4>${esc(e.title)}</h4><p>${esc(e.evidence)}</p><p class="workspaceHint">${esc(e.date_text)}${e.starts_at?'':' · 请补充完整日期和时间'}</p><button class="secondary" onclick="confirmMailEvent(${i})">核对并添加</button></article>`).join('')}catch(e){if(epoch===workspaceEpoch&&document.getElementById('mailStatus'))document.getElementById('mailStatus').textContent=e.message}finally{button.disabled=false}}
function confirmMailEvent(index){const e=mailCandidates[index];editWorkspaceEvent(null,{...e,details:'原文依据：'+e.evidence})}
window.addEventListener('beforeunload',event=>{if(workspaceDirty||workspaceSaving){event.preventDefault();event.returnValue=''}});

function resetCourseWorkspace(){if(typeof resetNoteMedia==='function')resetNoteMedia();workspaceEpoch++;clearTimeout(workspaceSaveTimer);workspaceDirty=false;workspaceNote=null;workspaceSaving=null;workspaceNotes=[];workspaceEvents=[];workspaceLinks=[];learningPurpose='study';learningDraftScope='';document.getElementById('courseDialog')?.remove()}

async function readSyllabusForCalendar(file){if(!file)return;const epoch=workspaceEpoch;try{document.getElementById('mailStatus').textContent='正在读取文件…';const value=await readCoursewareText(file);if(epoch!==workspaceEpoch)return;if(value.length>24000)throw Error('大纲文字超过 24000 字，请只粘贴时间安排和考核要求部分。');document.getElementById('mailText').value=value;document.getElementById('mailStatus').textContent='已读取，请核对后点击提取。'}catch(e){if(epoch===workspaceEpoch)document.getElementById('mailStatus').textContent=e.message}}

async function beginSemesterPlanning(){await closeCourseDialog();changeLearningScope('all');clearLearningConversation();learningPurpose='planning';learningDraft='我想做选课和学期规划。先询问我的候选课程、毕业要求、目标和每周可用时间，再一起安排。';saveLearningDraft();renderStudyAssistant();document.getElementById('materialPrompt')?.focus()}

function showFirstCourseDialog(tab){courseDialog('创建第一门课',`<p class="workspaceHint">先给这门课一个名称，再导入 syllabus 或课件。</p><form onsubmit="createWorkspaceCourse(event,'${tab}')"><label for="firstCourseName">课程名称或课号</label><input id="firstCourseName" maxlength="120" required><button class="secondary">创建并继续</button><p id="firstCourseError" role="alert"></p></form>`)}
async function createWorkspaceCourse(event,tab){event.preventDefault();const b=event.target.querySelector('button');b.disabled=true;try{const name=document.getElementById('firstCourseName').value.trim(),[course]=await sb('user_courses',{method:'POST',body:JSON.stringify({user_id:session.user.id,name,code:/^[A-Za-z]{2,6}\d{3,5}$/.test(name)?name.toUpperCase():'',weeks:13})});courseRows.push(course);await closeCourseDialog();if(['notebook','words','calendar'].includes(tab))await enterStudyToolCourse(tab,course.id);else await showCourseWorkspace(tab,course.id)}catch(e){document.getElementById('firstCourseError').textContent=e.message;b.disabled=false}}
async function importWorkspaceNote(file){if(!file)return;if(file.size>1024*1024)return alert('笔记文件请控制在 1 MB 内。');const epoch=workspaceEpoch;try{const body=/\.md$/i.test(file.name)?await file.text():await readCoursewareText(file);if(epoch!==workspaceEpoch)return;if(body.length>60000)throw Error('单篇笔记最多 60000 字，请拆分后导入。');editWorkspaceNote();document.getElementById('noteTitle').value=file.name.replace(/\.[^.]+$/,'').slice(0,120);document.getElementById('noteBody').value=body;scheduleNoteSave()}catch(e){alert(e.message)}}
async function deleteWorkspaceNote(){if(!workspaceNote||!confirm('删除这篇笔记？需要保留时请先导出。'))return;clearTimeout(workspaceSaveTimer);if(workspaceSaving)await workspaceSaving;try{if(workspaceNote.version)await sb('user_course_notes?id=eq.'+workspaceNote.id,{method:'DELETE'});workspaceNotes=workspaceNotes.filter(n=>n.id!==workspaceNote.id);try{removeWorkspaceDraft(noteDraftKey(workspaceNote.id))}catch{}workspaceNote=null;workspaceDirty=false;renderCourseWorkspace()}catch(e){document.getElementById('noteSaveStatus').textContent='未删除：'+e.message}}
async function importBatchSyllabus(index,courseId){const f=materialState?.files[index];if(!f?.text)return;const course=courseId||f.plan?.course||courseRows.find(c=>c.code&&f.name.toLowerCase().includes(c.code.toLowerCase()))?.id||workspaceScope();await showCourseWorkspace('calendar',course);if(!document.getElementById('workspaceContent'))return;showMailImport('syllabus');if(f.text.length<=24000)document.getElementById('mailText').value=f.text;else document.getElementById('mailStatus').textContent='已找到大纲，请粘贴其中的时间安排部分（最多 24000 字）。'}

function noteDraftKey(id){return 'courselex-note-draft:'+session.user.id+':'+id}
function noteDraftStores(){const stores=[];for(const get of [()=>localStorage,()=>sessionStorage])try{const store=get();if(store)stores.push(store)}catch{}return stores}
function validWorkspaceDraft(d,uid,id,course){return d&&d.id===id&&(!d.draft_owner||d.draft_owner===uid)&&(!course||d.course_id===course)&&typeof d.title==='string'&&typeof d.body==='string'&&Number.isInteger(d.version)&&d.version>=0}
function readWorkspaceDraft(id,course){if(!session)return null;let latest=null;for(const store of noteDraftStores())try{const d=JSON.parse(store.getItem(noteDraftKey(id))||'null');if(validWorkspaceDraft(d,session.user.id,id,course)&&(!latest||(Date.parse(d.updated_at)||0)>(Date.parse(latest.updated_at)||0)))latest=d}catch{}return latest}
function appendWorkspaceDrafts(uid,course,week=null){if(session?.user.id!==uid)return;const ids=new Set();for(const store of noteDraftStores())try{for(let i=0;i<store.length;i++){const key=store.key(i),prefix='courselex-note-draft:'+uid+':';if(key?.startsWith(prefix))ids.add(key.slice(prefix.length))}}catch{}for(const id of ids){const draft=readWorkspaceDraft(id,course);if(draft&&(!week||Number(draft.week)===Number(week))&&!workspaceNotes.some(n=>n.id===id))workspaceNotes.push(draft)}}
function removeWorkspaceDraft(key,expected){for(const store of noteDraftStores())try{if(expected){const draft=JSON.parse(store.getItem(key)||'null');if(draft&&['title','body','paper_style'].some(k=>(k==='title'?(draft.title?.trim()||'未命名笔记'):(draft[k]||''))!==(expected[k]||'')))continue}store.removeItem(key)}catch{}}
function persistWorkspaceNoteDraft(){if(!workspaceNote||!session)return false;const draft={...workspaceNote,draft_owner:session.user.id,title:document.getElementById('noteTitle').value,body:document.getElementById('noteBody').value,paper_style:document.getElementById('notePaperStyle')?.value||workspaceNote.paper_style||'blank',course_id:workspaceCourse,updated_at:new Date().toISOString()},value=JSON.stringify(draft);let durable=false;for(const store of noteDraftStores())try{store.setItem(noteDraftKey(workspaceNote.id),value);try{if(store===localStorage)durable=true}catch{}}catch{}return durable}

function hasSavedUnscopedConversation(){try{return !!localStorage.getItem(learningStorageKey())}catch{return false}}

async function openCourseMaterials(courseId){
 if((workspaceDirty||workspaceSaving)&&!await flushWorkspace())return;
 const course=courseRows.find(c=>c.id===(courseId||workspaceScope())&&!c.archived);if(!course)return chooseToolCourse('materials');
 workspaceCourse=course.id;if(!courseDialog('课程课件',`<p class="workspaceHint">${esc(course.code||course.name)} · 学习时可以直接引用这里的内容。</p><div id="courseSourceList">正在读取课件…</div>`))return;
 const epoch=++workspaceEpoch;try{const rows=await sb('user_learning_sources?select=id,filename,week,content_chars&course_id=eq.'+course.id+'&order=week.asc,created_at.asc');if(epoch!==workspaceEpoch)return;
 document.getElementById('courseSourceList').innerHTML=`<div class="workspaceRow"><button class="secondary" onclick="addFocusedCourseMaterial()">＋ 添加课件</button><button class="newChat" onclick="showMaterialsLibraryFromTool()">管理课程与词汇</button></div>${rows.length?rows.map(r=>`<article class="sourceItem"><span class="sourceFileIcon">${lexIcon('file')}</span><div><strong>${esc(r.filename)}</strong><small>Week ${r.week} · 已保存文字</small></div><button class="newChat" onclick="readFocusedCourseSource('${r.id}')">查看文字</button></article>`).join(''):'<p class="workspaceEmpty">这门课还没有保存课件文字。添加课件后，就能围绕内容学习。</p>'}`;
 }catch(e){if(epoch===workspaceEpoch)document.getElementById('courseSourceList').textContent='读取课件失败：'+e.message}
}
async function addFocusedCourseMaterial(){const c=workspaceCourse;if(await closeCourseDialog()===false)return;if(assistantScope!==c)changeLearningScope(c);else renderStudyAssistant();document.querySelector('.attachButton input')?.click()}
async function showMaterialsLibraryFromTool(){if(await closeCourseDialog()===false)return;showMaterialsLibrary()}
async function readFocusedCourseSource(id){const epoch=++workspaceEpoch;const rows=await sb('user_learning_chunks?source_id=eq.'+encodeURIComponent(id)+'&select=ordinal,content&order=ordinal.asc');if(epoch!==workspaceEpoch)return;document.getElementById('courseSourceList').innerHTML='<button class="newChat" onclick="openCourseMaterials(workspaceCourse)">← 课件列表</button><p class="workspaceHint">以下是保存的提取文字，不代表已完整识别图表。</p><div class="sourceReading">'+rows.map(r=>'<p>'+esc(r.content)+'</p>').join('')+'</div>'}

function chooseToolCourse(tab){const rows=courseRows.filter(c=>!c.archived&&!c.is_shared_template);if(!rows.length)return showFirstCourseDialog(tab);courseDialog('先选择一门课',`<p class="workspaceHint">把这次操作保存在对应课程里。</p><div class="toolCourseChoices">${rows.map(c=>`<button class="noteItem" onclick="showCourseWorkspace('${tab}','${c.id}')">${esc(c.code||c.name)}</button>`).join('')}</div>`)}

// Inline notebook: reuse the versioned note writer and local draft recovery.
let notebookSerial=0,notebookFreshEntry=false,toolWeekSerial=0;
function isNotebookSplit(){return typeof readingPane!=='undefined'&&readingPane.open&&Boolean(document.getElementById('notebookMount'))}
function notebookSelectionKey(){return 'courselex-notebook:'+session.user.id+':'+workspaceCourse+':'+(readingPane.week||'all')}
function rememberNotebookNote(id){try{localStorage.setItem(notebookSelectionKey(),id)}catch{}if(typeof saveReadingResume==='function')saveReadingResume()}
function chooseNotebookCourse(){return chooseStudyToolCourse('notebook')}
async function chooseStudyToolCourse(tool){
 const labels={notebook:'课件与笔记',words:'背单词',calendar:'学习安排'};
 if(!labels[tool]||!session||assistantBusy||!await flushWorkspace())return;
 const rows=courseRows.filter(c=>!c.archived&&!c.is_shared_template);
 if(!rows.length)return showFirstCourseDialog(tool);
 courseDialog('想学习哪门课？',`<p class="workspaceHint">选择课程，进入${labels[tool]}。</p><div class="toolCourseChoices notebookCourseChoices">${rows.map(c=>`<button class="noteItem" onclick="enterStudyToolCourse('${tool}','${c.id}')"><span><strong>${esc(c.code||c.name)}</strong>${c.code&&c.name!==c.code?`<small>${esc(c.name)}</small>`:''}</span><span aria-hidden="true">→</span></button>`).join('')}</div><button class="newChat" onclick="showFirstCourseDialog('${tool}')">＋ 添加课程</button>`);
}
async function enterStudyToolCourse(tool,courseId){
 if(!['notebook','words','calendar'].includes(tool)||!session||assistantBusy||!await flushWorkspace())return;
 const course=courseRows.find(c=>c.id===courseId&&!c.archived&&!c.is_shared_template);if(!course)return;
 if(tool!=='calendar')return chooseStudyToolWeek(tool,course.id);
 if(!await closeCourseDialog())return;
 return showCourseWorkspace('calendar',course.id);
}
async function chooseStudyToolWeek(tool,courseId){
 const course=courseRows.find(c=>c.id===courseId&&!c.archived&&!c.is_shared_template);if(!course||!['notebook','words'].includes(tool)||!session)return;
 const uid=session.user.id,serial=++toolWeekSerial;
 courseDialog('选择学习周次',`<p class="workspaceHint">${esc(course.code||course.name)} · ${tool==='words'?'背单词':'课件与笔记'}</p><div id="toolWeekContent">正在读取周次…</div><button class="newChat" onclick="chooseStudyToolCourse('${tool}')">← 重新选课程</button>`);
 const target=document.getElementById('toolWeekContent');if(!target)return;
 try{
  const sources=tool==='notebook'?await sb('user_learning_sources?select=id,course_id,filename,week&course_id=eq.'+course.id+'&order=week.asc,created_at.asc'):[];
  if(serial!==toolWeekSerial||session?.user.id!==uid||!target.isConnected)return;
  const pool=tool==='words'?words.filter(w=>w.course===course.id):sources;
  const found=[...new Set(pool.map(r=>Number(r.week)).filter(w=>Number.isInteger(w)&&w>0&&w<=52))].sort((a,b)=>a-b);
  const weeks=tool==='words'?found:Array.from({length:Math.min(52,Math.max(Number(course.weeks)||13,...found))},(_,i)=>i+1);
  if(!weeks.length){target.innerHTML='<p class="workspaceEmpty">这门课还没有可背的词汇，先添加课件或词表，再选择学习周次。</p>';return}
  const options=weeks.map(week=>({value:String(week),label:'Week '+week+' · '+(tool==='words'?pool.filter(r=>Number(r.week)===week).length+' 个词':pool.filter(r=>Number(r.week)===week).length+' 份课件')}));
  target.innerHTML=renderStudyPicker('toolWeek','周次','',options,()=>{document.getElementById('toolWeekEnter').disabled=false})+`<p class="workspaceHint">${tool==='notebook'?'进入所选周次，接着阅读和编辑自己的笔记；没有课件也可以先记笔记。':'只学习所选周次的词汇。'}</p><button id="toolWeekEnter" class="secondary" disabled onclick="confirmStudyToolWeek('${tool}','${course.id}')">进入${tool==='words'?'背单词':'课件与笔记'}</button>`;
 }catch(e){if(serial===toolWeekSerial&&target.isConnected)target.textContent='周次暂时无法读取，请重新选择课程。'}
}
async function switchStudyToolCourse(tool,courseId){
 if(assistantBusy||typeof answerBusy!=='undefined'&&answerBusy||!await flushWorkspace())return;
 await chooseStudyToolWeek(tool,courseId);
 if(tool==='notebook')renderNotebookRangeControls();
 if(tool==='words'){const scope=document.querySelector('.vocabularyScope');if(scope)scope.outerHTML=vocabularyStudyControls()}
}
function renderNotebookRangeControls(){
 const target=document.getElementById('notebookRangeControls'),course=workspaceScope();if(!target)return;
 const row=courseRows.find(c=>c.id===course),available=courseRows.filter(c=>!c.archived&&!c.is_shared_template);
 const total=Math.min(52,Math.max(Number(row?.weeks)||13,Number(readingPane.week)||1,...learningState.sources.filter(s=>s.course_id===course).map(s=>Number(s.week)||1)));
 target.innerHTML=renderStudyPicker('notebookCourse','课程',course,available.map(c=>({value:c.id,label:c.code||c.name})),id=>switchStudyToolCourse('notebook',id))+renderStudyPicker('notebookWeek','周次',String(readingPane.week||''),Array.from({length:total},(_,i)=>({value:String(i+1),label:'Week '+(i+1)})),week=>switchNotebookWeek(week));
 const label=document.querySelector('.notebookPanel>header small');if(label)label.textContent=(row?.code||row?.name||'当前课程')+(readingPane.week?' · Week '+readingPane.week:'');
}
async function switchNotebookWeek(value){
 const week=Number(value);if(!Number.isInteger(week)||week<1||week>52)return;
 if(!await flushWorkspace()){renderNotebookRangeControls();return}
 if(week!==readingPane.week)await openNotebookSplit(null,workspaceScope(),week);
 renderNotebookRangeControls();
}
async function confirmStudyToolWeek(tool,courseId){
 const raw=document.getElementById('toolWeek')?.value,week=Number(raw),course=courseRows.find(c=>c.id===courseId&&!c.archived&&!c.is_shared_template);
 if(!course||!['words','notebook'].includes(tool)||!Number.isInteger(week)||week<1||week>52||assistantBusy||!await flushWorkspace())return;
 if(tool==='words'&&!words.some(w=>w.course===courseId&&Number(w.week)===week))return;
 if(!await closeCourseDialog())return;
 if(tool==='notebook')return openNotebookSplit(null,course.id,week);
 if(assistantScope!==course.id)changeLearningScope(course.id);
 return startDailyStudy(false,{course:course.id,week});
}
async function openNotebookSplit(noteId,courseId,week){
 if(!await flushWorkspace())return;
 if(typeof saveReadingResume==='function')saveReadingResume();
 const resumeUid=session?.user.id;if(typeof pullStudySync==='function'&&courseId){await flushStudySync();await pullStudySync('reader',courseId,week);if(resumeUid!==session?.user.id)return}
 const course=courseId||workspaceCourse||workspaceScope();if(!courseRows.some(c=>c.id===course&&!c.archived&&!c.is_shared_template))return;
 if(!await closeCourseDialog())return;
 workspaceCourse=course;if(assistantScope!==course)changeLearningScope(course);
 const selectedNote=noteId&&workspaceNotes.find(n=>n.id===noteId);if(selectedNote&&week===undefined){readingPane.week=selectedNote.week||null;readingPane.key='';readingPane.html='';readingPane.id='';readingPane.scroll=0}
 if(week){readingPane.week=Number(week);readingPane.id='';readingPane.key='';readingPane.html='';readingPane.scroll=0;readingPane.page=Array.isArray(window.SINQ_LECTURE_PAGES)?window.SINQ_LECTURE_PAGES[0]:1;notebookFreshEntry=false;if(typeof restoreReadingResume==='function')restoreReadingResume(course,Number(week));const mount=document.getElementById('notebookMount');if(mount)mount.dataset.loadedCourse=''}
 readingPane.open=true;readingPane.tab='source';readingPane.mobile='notebook';readingPane.aiOpen=false;rememberNotebookMode();renderStudyAssistant();if(noteId)await loadNotebook(noteId);
}
async function loadNotebook(noteId){
 const mount=document.getElementById('notebookMount'),uid=session?.user.id,course=workspaceScope();if(!mount)return;
 if(!course){mount.textContent='请先退出分屏，选择一门课程，再开始记笔记。';return}
 const requestedWeek=readingPane.week||null,serial=++notebookSerial,fresh=notebookFreshEntry;notebookFreshEntry=false;if(!await flushWorkspace())return;
 workspaceCourse=course;workspaceTab='notes';mount.dataset.loadedCourse='loading:'+course;
 try{
  if(typeof pullStudySync==='function'){await pullStudySync('reader',course,requestedWeek);if(serial!==notebookSerial||uid!==session?.user.id||(readingPane.week||null)!==requestedWeek)return;restoreReadingResume(course,requestedWeek);loadReadingPane()}

  const notes=await sb('user_course_notes?course_id=eq.'+course+(readingPane.week?'&week=eq.'+Number(readingPane.week):'')+'&order=updated_at.desc');
  if(serial!==notebookSerial||uid!==session?.user.id||workspaceScope()!==course||(readingPane.week||null)!==requestedWeek||!isNotebookSplit())return;
  workspaceNotes=notes;
  appendWorkspaceDrafts(uid,course,requestedWeek);
  let remembered;try{remembered=localStorage.getItem(notebookSelectionKey())||sessionStorage.getItem(notebookSelectionKey())}catch{}
  const selected=fresh?null:workspaceNotes.find(n=>n.id===(noteId||remembered))||workspaceNotes[0];
  editWorkspaceNote(selected?.id);rememberNotebookNote(workspaceNote.id);renderNotebookControls();mount.dataset.loadedCourse=course;
 }catch(e){if(serial===notebookSerial){mount.dataset.loadedCourse='';document.getElementById('workspaceContent').textContent='笔记暂时无法打开：'+e.message}}
}
function renderNotebookControls(){renderNotebookRangeControls();const target=document.getElementById('notebookPicker');if(!target||!workspaceNote)return;const notes=workspaceNotes.some(n=>n.id===workspaceNote.id)?workspaceNotes:[workspaceNote,...workspaceNotes];target.innerHTML=renderStudyPicker('notebookNote','选择笔记',workspaceNote.id,notes.map(n=>({value:n.id,label:n.title||'未命名笔记'})),switchNotebookNote)}
async function switchNotebookNote(id){if(!await flushWorkspace()){renderNotebookControls();return}editWorkspaceNote(id);rememberNotebookNote(id);renderNotebookControls()}
async function newNotebookNote(){if(!await flushWorkspace())return;editWorkspaceNote();rememberNotebookNote(workspaceNote.id);renderNotebookControls();document.getElementById('noteTitle')?.focus()}

// Check remote changes without replacing a draft, an in-flight save, or active typing.
let noteRefreshFlight=false;
async function refreshOpenWorkspaceNote(){
 if(noteRefreshFlight||!session||!workspaceNote?.version||workspaceDirty||workspaceSaving||document.visibilityState==='hidden')return;
 if(['noteTitle','noteBody','noteTextBody'].includes(document.activeElement?.id))return;
 const uid=session.user.id,id=workspaceNote.id,epoch=workspaceEpoch,version=workspaceNote.version,course=workspaceCourse;
 if(!document.getElementById('noteBody'))return;noteRefreshFlight=true;
 try{const rows=await sb('user_course_notes?id=eq.'+id+'&course_id=eq.'+course);
  if(session?.user.id!==uid||workspaceEpoch!==epoch||workspaceNote?.id!==id||workspaceNote.version!==version||workspaceDirty||workspaceSaving||document.visibilityState==='hidden'||['noteTitle','noteBody','noteTextBody'].includes(document.activeElement?.id))return;
  const remote=rows[0];if(remote&&remote.version>version){const reading=document.querySelector?.('[data-note-view="read"]')?.getAttribute('aria-pressed')==='true';workspaceNotes=[remote,...workspaceNotes.filter(n=>n.id!==id)];editWorkspaceNote(id);if(reading&&typeof setNoteView==='function')setNoteView('read');document.getElementById('noteSaveStatus').textContent='已载入另一设备更新 · 本篇笔记已同步'}
 }catch{const status=document.getElementById('noteSaveStatus');if(status&&session?.user.id===uid&&workspaceEpoch===epoch&&workspaceNote?.id===id&&!workspaceDirty&&!workspaceSaving)status.textContent='暂时无法检查其他设备更新；当前笔记未改动'}finally{noteRefreshFlight=false}
}
async function resumeWorkspaceNoteSync(){if(!session||!workspaceNote||!document.getElementById('noteBody'))return;if(workspaceDirty){const conflict=document.getElementById('noteConflict');if(conflict&&!conflict.hidden)return;await saveWorkspaceNote()}else await refreshOpenWorkspaceNote()}
if(typeof window!=='undefined'&&window.addEventListener){
 window.addEventListener('online',resumeWorkspaceNoteSync);
 window.addEventListener('focus',()=>{if(typeof document!=='undefined')resumeWorkspaceNoteSync()});
 if(window.setInterval)window.setInterval(refreshOpenWorkspaceNote,20000);
 if(typeof document!=='undefined'&&document.addEventListener)document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){if(workspaceDirty)persistWorkspaceNoteDraft()}else resumeWorkspaceNoteSync()});
}
